	/**
	 * Default Constructor
	 */
    public PublisherService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new PublisherEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(PublisherRepository.class) );
		this.validator		= applicationContext.getBean(PublisherValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Publisher
	 */
		public Publisher createPublisher( CreatePublisherCommand command ) {

		Publisher entity = new Publisher();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setPublisherId( command.getPublisherId() );
            entity.setName( command.getName() );
            entity.setWebsite( command.getWebsite() );
            entity.setPublisherType( command.getPublisherType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Publisher {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdatePublisherCommand
	 * @return		Publisher
	 */
	public Publisher updatePublisher( UpdatePublisherCommand command ) {

		Publisher entity = new Publisher();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setPublisherId( command.getPublisherId() );
            entity.setName( command.getName() );
            entity.setWebsite( command.getWebsite() );
            entity.setInventorySources( command.getInventorySources() );
            entity.setDeals( command.getDeals() );
            entity.setCreativeApprovals( command.getCreativeApprovals() );
            entity.setInsertionOrders( command.getInsertionOrders() );
            entity.setRateCards( command.getRateCards() );
            entity.setPublisherType( command.getPublisherType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Publisher {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeletePublisherCommand
	 */
	public void delete( DeletePublisherCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getPublisherId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Publisher {0} ", id );

	}

	/**
	 * Method to retrieve the Publisher via PublisherFetchOneSummary
	 * @param 	summary PublisherFetchOneSummary
	 * @return 	PublisherFetchOneResponse
	 */
	public Publisher getPublisher( PublisherFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "PublisherFetchOneSummary arg cannot be null" );

		Publisher entity = null;
		UUID id = summary.getPublisherId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Publisher using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Publishers
	 *
	 * @return 	List<Publisher>
	 */
    public List<Publisher> getAllPublisher() {
		List<Publisher> list = projector.findAll( new FindAllPublisherQuery() );
		return list;
	}


